// lib/feed/pinterest-gtin.ts
//
// GTIN TILL PINTEREST-FLÖDET (Leonard 2026-11-15). Bara /feed/pinterest.xml läser
// den här kartan. Google-, PriceRunner- och Prisjakt-flödena rörs inte.
//
// VARFÖR. Pinterest använder GTIN för att känna igen en produkt och visa den i
// shoppingytorna. Utan kod är varan fortfarande med, bara sämre matchad.
//
// VAR KODERNA KOMMER IFRÅN. Uppslagslistan "Fyndplats-GTIN-lista-2026-11-14-v3"
// (Leonards fil, ifylld 2026-11-14): koden står på en CDON-annons där säljarens
// artikelnummer (sku) är exakt vårt leverantörsnummer för just den varianten,
// för Aosom hos säljaren AOSOM. Kontrollsiffran stämmer på varje kod.
//
// VAD SOM INTE ÄR MED, med flit:
//  - Raderna med en annan källa än CDON (Kaufland) och raderna utan exakt
//    samma artikelnummer. Listan säger själv att de ska bekräftas först.
//  - Varianter där Prisjakt-kartan (lib/feed/prisjakt-gtin.ts) har en ANNAN kod.
//    492 Aosom-varianter krockade 2026-11-15, oftast med en kod ett eller två
//    steg ifrån (en syskonfärg). Någon av källorna har fel, och vi vet inte vilken,
//    så de får ingen kod alls här förrän det är utrett.
//  - En kod som står på två varor, eller på en annan vara i Prisjakt-kartan.
//
// ⚠️ Leonard 2026-11-15: "aosom koderna får också läggas in". Före det gällde att
// Aosom-varor aldrig fick en kod i Google. Det beslutet gäller fortfarande Google.
//
// SÅ BACKAR MAN. Töm PINTEREST_GTIN_AOSOM eller PINTEREST_GTIN_VEVOR till `{}`.
// Flödet blir då utan de koderna och i övrigt detsamma.
//
// Repot är publikt: bara variant-id och kod står här, aldrig leverantörens
// artikelnummer, inköpspriser eller adresser. pinterest-gtin.test.ts vaktar formen.

